T = ["Günümüz meseleleri","Toplum ve iletişim"]
S = ["Günümüz meseleleri","Tıp ve sağlık"]
M = [
{"id":"komsuhakki","yol":T,"baslik":"Komşu hakkı ve apartman hayatı","ar":"حق الجار",
 "hanefi":"Komşuya iyilik etmek ve eziyet etmemek Kur’an’ın emridir; Müslim olsun gayrimüslim olsun her komşunun hakkı vardır. Apartman hayatında gürültü yapmak, ortak alanları kirletmek, aidat ve ortak giderleri ödememek, otoparkı ve merdiveni işgal etmek komşu hakkını çiğnemektir. Kurban, mevlit veya düğün gibi etkinliklerde komşuları rahatsız etmemek, ikram ve hediyeyle gönüllerini almak sünnettir.",
 "mez":{"maliki":["Aynı","Komşuya zarar veren tasarruf engellenir."],
        "safii":["Aynı","Ahlaki yükümlülük esastır."],
        "hanbeli":["Aynı","Komşunun duvarına kiriş koyma hakkı hadisine dayanılır."]},
 "sebep":"Mezheplerde ittifak vardır; ayrılık, mülk sahibinin komşuya zarar veren tasarrufunun hukuken engellenip engellenemeyeceğindedir.",
 "delil":[["ayet","Nisâ 4:36","./#4-36","“…Yakın komşuya, uzak komşuya… iyilik edin.”"],
          ["hadis","“Komşusu kötülüğünden emin olmayan iman etmiş olmaz.”",hadis("والله لا يؤمن الذي لا يأمن جاره بوائقه"),"Buhârî, Edeb, 29."]],
 "usul":"“Zarar vermek de zarara zararla karşılık vermek de yoktur” kaidesi komşuluk hukukunun temelidir."},
{"id":"hastaziyaret","yol":T,"baslik":"Hasta ziyareti","ar":"عيادة المريض",
 "hanefi":"Hasta ziyareti, Müslümanın Müslüman üzerindeki haklarından biridir ve sünnettir; hastaya moral vermek, dua etmek ve ihtiyaçlarını sormak gerekir. Ziyaret kısa tutulmalı, hastanın dinlenme ve tedavi düzenine, hastane kurallarına ve bulaşıcı hastalıklarda sağlık tedbirlerine uyulmalıdır. Gayrimüslim hastayı ziyaret etmek de caizdir; Hz. Peygamber Yahudi bir çocuğu ziyaret etmiştir.",
 "mez":{"maliki":["Sünnet","Farz-ı kifâye diyenler de vardır."],
        "safii":["Sünnet","Gayrimüslim komşu ve akrabayı ziyaret caizdir."],
        "hanbeli":["Sünnet","Bid‘atçı olmayan herkes ziyaret edilir."]},
 "sebep":"Ziyaret emrinin vücûb mu nedb mi ifade ettiği.",
 "delil":[["hadis","Müslümanın Müslüman üzerindeki beş hakkı",hadis("حق المسلم على المسلم خمس رد السلام وعيادة المريض"),"Buhârî, Cenâiz, 2; Müslim, Selâm, 4."],
          ["hadis","Hasta ziyaretinde okunacak dua",hadis("لا بأس طهور إن شاء الله"),"Buhârî, Merdâ, 10."]],
 "usul":"Toplumsal dayanışmayı sağlayan sünnetler, birlikte sorumluluk (farz-ı kifâye) anlayışıyla da değerlendirilmiştir."},
{"id":"bulasici","yol":S,"baslik":"Salgın hastalıkta cemaat ve cuma","ar":"صلاة الجماعة والجمعة في الوباء",
 "hanefi":"Salgın hastalık döneminde hastalığı yayma ihtimali bulunan kişilerin camiye gelmemesi, sağlık otoritelerinin tedbirlerine uyulması gerekir. Hastalık veya bulaştırma tehlikesi cuma ve cemaati terk etmek için meşru bir özürdür; bu kişiler öğle namazını evde kılar. Hastalığın kendisine bulaşmasından ciddi şekilde endişe eden yaşlı ve kronik hastalar için de ruhsat vardır. Saflarda maske ve mesafe gibi tedbirler zaruret hâlinde caizdir.",
 "mez":{"maliki":["Özür","Zarar korkusu cuma ve cemaatten muaf tutar."],
        "safii":["Özür","Bulaşıcı hastanın cemaate gelmesi engellenir."],
        "hanbeli":["Özür","Hastalık ve hastalık korkusu özürdür."]},
 "sebep":"Mezheplerde esasta ittifak vardır; özrün sınırı ve kamu otoritesinin kararlarının bağlayıcılığı.",
 "delil":[["hadis","“Bir yerde veba olduğunu duyarsanız oraya girmeyin…”",hadis("إذا سمعتم بالطاعون بأرض فلا تدخلوها"),"Buhârî, Tıb, 30; Müslim, Selâm, 98."],
          ["hadis","“Hasta deve sağlam devenin yanına getirilmesin.”",hadis("لا يورد ممرض على مصح"),"Buhârî, Tıb, 53; Müslim, Selâm, 104."]],
 "usul":"Canın korunması (hıfzu’n-nefs) şerîatın temel maksadıdır; “Zarar giderilir” ve “kamu zararı özel zarara tercih edilerek önlenir” kaideleri."},
{"id":"tedavicaiz","yol":S,"baslik":"Haram maddeyle tedavi","ar":"التداوي بالمحرمات",
 "hanefi":"Hastalıklar için tedavi olmak sünnettir. Haram veya necis maddeyle tedavi olmak aslen caiz değildir; ancak Müslüman ve uzman bir doktor, bu ilacın şifa vereceğini ve helal bir alternatifinin bulunmadığını bildirirse zaruret gereği caizdir. İçinde domuz kaynaklı madde veya alkol bulunan ilaçlarda, helal muadili varsa onun kullanılması gerekir; yoksa zaruret ölçüsünde kullanılabilir.",
 "mez":{"maliki":["Haram (yalnız dış kullanımda ruhsat)","İçilerek kullanılmaz."],
        "safii":["Zarurette caiz","Saf içki dışında necis maddelerle zarurette tedavi caizdir."],
        "hanbeli":["Caiz değil (meşhur)","Haramla tedavi edilmez."]},
 "sebep":"“Allah şifayı size haram kıldığı şeylerde yaratmamıştır” hadisinin zaruret hâlini de kapsayıp kapsamadığı.",
 "delil":[["hadis","“Allah hem hastalığı hem ilacı indirdi… tedavi olun, haramla tedavi olmayın.”",hadis("إن الله أنزل الداء والدواء فتداووا ولا تداووا بحرام"),"Ebû Dâvûd, Tıb, 11."],
          ["hadis","Ureyneliler’e deve sütü ve idrarının tavsiye edilmesi",hadis("فأمرهم أن يشربوا من أبوالها وألبانها"),"Buhârî, Vudû, 66; Müslim, Kasâme, 9."],
          ["ayet","En‘âm 6:119","./#6-119","“…Zorda kaldığınız durumlar hariç, Allah size haram kıldıklarını açıklamıştır.”"]],
 "usul":"Zaruret, haramı mubah kılar; ancak şifanın kesin veya kuvvetli zan ile bilinmesi ve helal alternatifin bulunmaması şarttır."},
{"id":"engelliibadet","yol":S,"baslik":"Engellilerin ibadetleri","ar":"عبادات ذوي الاحتياجات الخاصة",
 "hanefi":"Allah kimseye gücünün üstünde yük yüklemez; engelli kişiler gücü yettiği kadarıyla ibadet eder. Ayakta duramayan oturarak, oturamayan yatarak ima ile namaz kılar. Abdest almaya gücü yetmeyen başkasının yardımıyla abdest alır, bu da mümkün değilse teyemmüm eder. İşitme engelliler namazı görerek öğrenir; zihinsel engelli kişi aklî melekesi yerinde değilse dinî yükümlülükten muaftır. Camilerin engellilerin erişimine uygun düzenlenmesi toplumun görevidir.",
 "mez":{"maliki":["Aynı","Güç yetirilen kadar ibadet."],
        "safii":["Aynı","Hiçbir şey yapamayan, rükünleri kalbinden geçirir."],
        "hanbeli":["Aynı","Gözüyle ima eder."]},
 "sebep":"Mezheplerde esasta ittifak vardır; ayrılık, başını da hareket ettiremeyen kişinin namazının düşüp düşmediğindedir.",
 "delil":[["ayet","Bakara 2:286","./#2-286","“Allah kimseye gücünün üstünde yük yüklemez.”"],
          ["ayet","Nûr 24:61","./#24-61","“Kör olana güçlük yoktur, topala güçlük yoktur, hastaya da güçlük yoktur…”"],
          ["hadis","İmrân b. Husayn hadisi",hadis("صل قائما فإن لم تستطع فقاعدا"),"Buhârî, Taksîrü’s-salât, 19."]],
 "usul":"Teklif, güce (istitaat) bağlıdır; “Yapılabilen, yapılamayan sebebiyle terk edilmez” kaidesi."},
]
